using System;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Reflection;
using System.Windows.Forms;
public class ClientSetup : Form {
 readonly string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","APTechClient");
 [STAThread] static void Main(){Application.EnableVisualStyles();Application.Run(new ClientSetup());}
 ClientSetup(){Text="Install AP Tech Client 1.0.0";ClientSize=new Size(530,265);Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath)??SystemIcons.Application;Font=new Font("Segoe UI",10);Controls.Add(new Label{Text="AP Tech Client\n\nView your jobs, progress and project conversations.\nUses your existing website login. No activity monitoring.\nWindows 10/11 x64 · Microsoft WebView2 Runtime required.",Left=24,Top=24,Width=480,Height=150});var install=new Button{Text="Install and open",Left=24,Top=195,Width=230,Height=38};install.Click+=(s,e)=>Install();Controls.Add(install);var remove=new Button{Text="Uninstall",Left=275,Top=195,Width=230,Height=38};remove.Click+=(s,e)=>Remove();Controls.Add(remove);}
 void Link(string location,string target){var type=Type.GetTypeFromProgID("WScript.Shell");var shell=Activator.CreateInstance(type);var link=type.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{Path.Combine(location,"AP Tech Client.lnk")});link.GetType().InvokeMember("TargetPath",BindingFlags.SetProperty,null,link,new object[]{target});link.GetType().InvokeMember("WorkingDirectory",BindingFlags.SetProperty,null,link,new object[]{folder});link.GetType().InvokeMember("Save",BindingFlags.InvokeMethod,null,link,null);}
 bool Running(){foreach(var p in Process.GetProcessesByName("APTechClient")){p.Dispose();return true;}return false;}
 void Install(){if(Running()){MessageBox.Show("Exit AP Tech Client from its tray menu first.");return;}try{Directory.CreateDirectory(folder);foreach(var file in Files()){using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream(file))using(var output=File.Create(Path.Combine(folder,file)))input.CopyTo(output);}var target=Path.Combine(folder,"APTechClient.exe");Link(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),target);Link(Environment.GetFolderPath(Environment.SpecialFolder.Programs),target);Process.Start(new ProcessStartInfo(target){UseShellExecute=true});Close();}catch(Exception ex){MessageBox.Show("Install failed: "+ex.Message);}}
 string[] Files(){return new[]{"APTechClient.exe","Microsoft.Web.WebView2.Core.dll","Microsoft.Web.WebView2.WinForms.dll","WebView2Loader.dll","WebView2-LICENSE.txt","WebView2-NOTICE.txt"};}
 void Remove(){if(Running()){MessageBox.Show("Exit the app first.");return;}if(MessageBox.Show("Remove AP Tech Client and shortcuts? Sign out in the app first to end the website session. Local browser profile is retained.","Uninstall",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;try{foreach(var file in Files()){var target=Path.Combine(folder,file);if(File.Exists(target))File.Delete(target);}foreach(var special in new[]{Environment.SpecialFolder.DesktopDirectory,Environment.SpecialFolder.Programs}){var link=Path.Combine(Environment.GetFolderPath(special),"AP Tech Client.lnk");if(File.Exists(link))File.Delete(link);}MessageBox.Show("Removed.");Close();}catch(Exception ex){MessageBox.Show(ex.Message);}}
}
